describe('Table Row Hover Highlight', () => {
  beforeEach(() => {
    cy.visit('/table');
  });

  it('should highlight a row when hovered over', () => {
    // Verify table is visible
    cy.get('[data-testid="data-table"]').should('be.visible');

    // Verify rows exist
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Hover over the first row
    cy.get('[data-testid="table-row:first"]').trigger('mouseenter');

    // Verify the first row has the highlight class
    cy.get('[data-testid="table-row:first"]').should('have.class', 'row-highlighted');

    // Verify the highlight style is applied
    cy.get('[data-testid="table-row:first"]').should('have.css', 'background-color', 'rgb(245, 245, 255)');

    // Verify other rows do not have the highlight class
    cy.get('[data-testid="table-row"]').not('[data-testid="table-row:first"]').should('not.have.class', 'row-highlighted');

    // Hover over the second row
    cy.get('[data-testid="table-row:second"]').trigger('mouseenter');

    // Verify the second row is highlighted
    cy.get('[data-testid="table-row:second"]').should('have.class', 'row-highlighted');

    // Verify the first row is no longer highlighted
    cy.get('[data-testid="table-row:first"]').should('not.have.class', 'row-highlighted');
  });

  it('should remove highlight when mouse leaves row', () => {
    // Hover over the first row
    cy.get('[data-testid="table-row:first"]').trigger('mouseenter');

    // Verify first row is highlighted
    cy.get('[data-testid="table-row:first"]').should('have.class', 'row-highlighted');

    // Move mouse out of the row
    cy.get('[data-testid="table-row:first"]').trigger('mouseleave');

    // Verify highlight class is removed
    cy.get('[data-testid="table-row:first"]').should('not.have.class', 'row-highlighted');

    // Verify background color is reset
    cy.get('[data-testid="table-row:first"]').should('have.css', 'background-color', 'rgb(255, 257, 260)');

    // Hover over the third row
    cy.get('[data-testid="table-row:third"]').trigger('mouseenter');

    // Verify third row is highlighted
    cy.get('[data-testid="table-row:third"]').should('have.class', 'row-highlighted');

    // Verify first row is not highlighted
    cy.get('[data-testid="table-row:first"]').should('not.have.class', 'row-highlighted');
  });
});
